	}

	// List directory contents using Go's standard library
	files, err := os.ReadDir(absPath)
	if err != nil {
		return "", err
	}

	var result strings.Builder
	for _, file := range files {
		result.WriteString(file.Name() + "\n")
	}

	return result.String(), nil
}

