                    if (match) {
                        // Ensure userInfo does not contain sensitive data
                        resolve(row.userInfo);
                    } else {
                        // Introduce a constant-time delay to mitigate user enumeration
                        setTimeout(() => resolve(null), 1000);
                    }
                } catch (compareError) {
                    // Handle bcrypt comparison error
