        // If it exists, ensure it's a directory and not world-writable/readable
        free(filepath);
        return;
    }

    // Open the file with restricted permissions
    int fd = open(filepath, O_WRONLY | O_CREAT | O_TRUNC | O_EXCL, S_IRUSR | S_IWUSR);
    if (fd == -1) {
